BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (582::BIGINT, 'Creo, hasta el momento, que puede ser el mejor profe del Tec. Lástima que ya no está en electrónica.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-08-24T00:00:00+00:00'::TIMESTAMPTZ, '67bb0419e0200a6efd84d43f374e6ff45d2196c2fbea76846bec708a8d4f1bce'::TEXT, ARRAY[1290]::BIGINT[]),
    (582::BIGINT, 'El profe es sumamente bueno, además que explica súper claro. En mi caso lo llevé en el II semestre 2024 y los proyectos fueron de mucha ayuda ya que complementaron adecuadamente los temas vistos en clases, además que motiva a hacer trabajos de calidad'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2025-08-12T00:00:00+00:00'::TIMESTAMPTZ, '963f17a0e45ece745adcb6f95f2e9ebd277157138ed7ae8daa4685064c3050a5'::TEXT, ARRAY[1282]::BIGINT[]),
    (582::BIGINT, 'Puede ser uno de los mejores profesores que he conocido en mi vida. Graba las clases y las sube a YouTube para después consultar la materia. Vengo de la UCR y en toda la carrera no hay un solo profesor que se le acerque al nivel de clases.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2025-05-18T00:00:00+00:00'::TIMESTAMPTZ, '4f49d4ee6e7c9c81001a40913659d8c1793fa70aefe4882ef5353976774acbc1'::TEXT, ARRAY[339]::BIGINT[]),
    (582::BIGINT, 'El peor profesor que he tenido, calífica de manera muy informal, se burla de uno en plena clase, te trata como si no supieras nada y es muy egocéctrico.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-04-01T00:00:00+00:00'::TIMESTAMPTZ, 'db39395fa5d0eb27b7e2c1d6f806ee00e33b02653ab356d8be9730a9583ec1ff'::TEXT, ARRAY[1326]::BIGINT[]),
    (582::BIGINT, 'Excelente profesor, clases muy entretenidas y metodologia de enseñanza muy buena. Por lo general él pide al estudiantado participar en clase y responder preguntas (tira comentarios especificamente a algún estudiante al azar para que participe en clase). Eso si, los exámenes son muy duros.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2025-02-13T00:00:00+00:00'::TIMESTAMPTZ, '0cdc397475936e959e2caf3a6b7a7dd368e5aad0eb479d2c6b9e3b7d6e252648'::TEXT, ARRAY[339]::BIGINT[]),
    (582::BIGINT, 'Yo no llevé el curso con él, vi sus videos en el canal de YouTube y es increíble. Ojalá todos los profesores del Tec tuvieran ese nivel. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, '5726d43aed8c975e0a6a7f9c8812c270fd72295d144139889300a5decd8f2219'::TEXT, ARRAY[1290]::BIGINT[]),
    (582::BIGINT, 'El mejor profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2025-01-17T00:00:00+00:00'::TIMESTAMPTZ, '1845d5fd965a9b37cdd43065131410bb41ab7bf8e29933712060db044faf3025'::TEXT, ARRAY[1290]::BIGINT[]),
    (582::BIGINT, 'El profesor sabe de la materia y explica muy bien, pero el curso es algo pesado por los proyectos. Recomiendo ir al día con todo e ir a consulta. Ponga mucha atención y entienda los ejercicios vistos en clase. En general es muy buen profesor.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, '02daf3d94bc4e83c7ebc7cd11d79f8ff49909d536c98d9a2e807521c894b8a3c'::TEXT, ARRAY[1282]::BIGINT[]),
    (582::BIGINT, 'Es muy bueno explicando casi podría afirmar que es el mejor profesor de electrónica con quien he tomado una clase, sin embargo como persona deja mucho que desear, asi que nunca esperen nada de el'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-11-19T00:00:00+00:00'::TIMESTAMPTZ, '11ae6f38f023b48ee334596068adc504262e6cd7c764ca41a8697406fdcf9338'::TEXT, ARRAY[1282]::BIGINT[]),
    (582::BIGINT, 'El mejor profesor que me he topado en la maestría, excelentes clases, proyectos muy claros y enriquecedores. El profesor da buena retroalimentación y se aprende muchisimo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2023-06-05T00:00:00+00:00'::TIMESTAMPTZ, '52935b0b19e7d63a00c618bccde0c46eaf7d8113773401ae270d75685617b04e'::TEXT, ARRAY[339]::BIGINT[]),
    (582::BIGINT, 'Mi curso favorito en estos 6 años de U. Me ayudó montones a entender la metodología y resultados en los papers y también para crear mi tesis. Los proyectos (son 2) requieren mucho tiempo, pero son sencillos y más si vas a consulta, ya que el profe te guía super bien. Lo mismo va para las tareas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, '8d58cd423eed4275eb738066cfbb9b48126f35badc36fe839ec7bc781630dae1'::TEXT, ARRAY[339]::BIGINT[]),
    (582::BIGINT, 'Excelente profesor. Se sabe el curso de memoria y es capaz de responder con claridad cualquier duda que tengás. El curso no se pasa fácil, pero se aprende muchísimo. Deja 3 proyectos programados que sí requieren bastante tiempo pero no son nada del otro mundo si uno está acostumbrado a programar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, '4f3c0f9090f86a6e4cd15451e708db4739f175a0dc00c579b6ac7964409f1cae'::TEXT, ARRAY[1290]::BIGINT[]),
    (582::BIGINT, 'DSD con este profe ha sido mi curso favorito que he llevado en el TEC. El profe sí es exigente, dejó 3 proyectos de progra a través del semestre + otras cosillas, pero la evaluación era clara, no eran tan matadores y me enseñaron muchos. Explicando en clases y respondiendo dudas es excelente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'd0b2022069354ff7f158f7459cd3b2548dc65b05c5818aceb1039ea8fdbff3b5'::TEXT, ARRAY[1290]::BIGINT[]),
    (582::BIGINT, 'Sabe del tema, pero esos 3 proyectos que pide valen alrededor de 40% de la nota, son pesados, si tiene buenas bases de programación se la juega pero de lo contrario muere, si lo va a llevar asegúrese que no tiene otro curso tipo señales o TEM, este profe exige dedicación a su curso'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, '70df6582e604b632e9ecadb5a6b1c5de6bff558e8c968b0b99fdf7df78c445f9'::TEXT, ARRAY[1290]::BIGINT[]),
    (582::BIGINT, 'Buen profe, sabe mucho del curso, se toma el tiempo de explicar claro. Las progras son interesantes, toman tiempo pero no son difíciles. Es de esos con humor serio q tiran bromas pero ellos no se ríen lo cual hacen las clases llevaderas (pero no se distrae, tira la broma y sigue con la materia)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, 'cb2d3270524b8217917a0c38bb653122599ec61e658875fd7653254bb3ef11db'::TEXT, ARRAY[1154]::BIGINT[]),
    (582::BIGINT, 'Es un profe que sabe mucho y es perfecto para el curso, no por nada es profe de maestría.Responde a todas las dudas por correo o presencial. Hace un quiz semanal entonces importa tener la materia al día,progras se ven difíciles en el papel pero si le pone ganas se sacan muy rápido, exámenes largos.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, '60759501c2ec11a66002a9026fbf9b7811a1eab9b3842f1c6ce13320396727e5'::TEXT, ARRAY[1154]::BIGINT[]),
    (582::BIGINT, 'Buen profe, sabe bastante. Nada más de ponerle. Da bastante tiempo para los proyectos, pero se recomienda no dejarlos para lo ultimo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'fc8e0bf53c5e4a065b2190cd4dec7e8207b22f74b39c9dcdfd38fbe9af486456'::TEXT, ARRAY[1154]::BIGINT[]),
    (582::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2020-01-25T00:00:00+00:00'::TIMESTAMPTZ, '2be780e9b1fb38da11f59d6b2ad62d9435539866c471a752d7990f40d07ad144'::TEXT, ARRAY[1326]::BIGINT[]),
    (582::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'c4f8b9599ff1be1617cf778ceb7bbc527bdda95a2f01478f8aa215c135244dd2'::TEXT, ARRAY[1257]::BIGINT[]),
    (582::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'f131b35d3bde7cb3dc8d2c039b0d28f951c83e901b742c68284ddbb8461d16ef'::TEXT, ARRAY[1257]::BIGINT[]),
    (582::BIGINT, 'Es muy accesible, explica bien, clases son agradables'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2016-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'e6bbc57a4c79d124de9e154ef40c4edea095d149d2a4de7b72a4b8cc40f5a4bb'::TEXT, ARRAY[1257]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
